package com.optarena;

public class Totals {
    // Return true when the two boxed order totals are equal in value.
    // BUG: `==` compares object references, not values. It happens to work for
    // small ints (the JVM caches -128..127) but returns false for larger equal
    // values such as sameTotal(1000, 1000).
    public boolean sameTotal(Integer a, Integer b) {
        return a == b;
    }
}

